"A booking is confirmed": "Tempahan disahkan",
"Create the invoice and send it to the guest": "Cipta invois dan hantar kepada tetamu",
"Invoice number assigned automatically. Direct bookings get it on WhatsApp, platform bookings by email. Same switch as the invoice settings in Invoices & Receipts.": "Nombor invois diberi secara automatik. Tempahan terus terima melalui WhatsApp, tempahan platform melalui e-mel. Suis yang sama dengan tetapan invois di Invois & Resit.",
"Auto": "Auto",
"Payment arrives for a booking": "Bayaran diterima untuk tempahan",
"Create the receipt and send it to the guest": "Cipta resit dan hantar kepada tetamu",
"The receipt is created as soon as the payment is recorded and sent at 6:00 PM that day, on the same channel as the invoice. Same switch as the receipt settings in Invoices & Receipts.": "Resit dibuat sebaik bayaran direkodkan dan dihantar pada 6:00 petang hari itu, melalui saluran yang sama dengan invois. Suis yang sama dengan tetapan resit di Invois & Resit.",
"Staff record an expense they paid personally": "Kakitangan merekod perbelanjaan yang dibayar sendiri",
"Ask the owner to approve the claim": "Minta pemilik luluskan tuntutan",
"The claim stays pending until an account owner approves it. Approval cannot be given to other roles.": "Tuntutan kekal menunggu sehingga pemilik akaun meluluskannya. Kelulusan tidak boleh diberi kepada peranan lain.",
"A booking is made for arrival today": "Tempahan dibuat untuk ketibaan hari ini",
"Alert the ops manager and create an urgent turnover task": "Maklumkan pengurus operasi dan cipta tugasan pusingan segera",
"If the unit still needs cleaning, the turnover for the property's housekeeper is marked urgent and due 15 minutes before arrival. If it is already clean, a pre-arrival inspection is created instead. The booking shows under Same-day bookings on the dashboard.": "Jika unit masih perlu dibersihkan, tugasan pusingan untuk pengemas hartanah ditanda segera dan perlu siap 15 minit sebelum ketibaan. Jika sudah bersih, pemeriksaan sebelum ketibaan dicipta. Tempahan dipaparkan di bawah Tempahan hari yang sama di papan pemuka.",
"A guest opens the door code in the guest app": "Tetamu membuka kod pintu dalam aplikasi tetamu",
"Show the house rules first and require acceptance": "Tunjuk peraturan rumah dahulu dan wajibkan persetujuan",
"The guest ticks agree and types their name. The door code stays hidden until rules are accepted and ID is verified.": "Tetamu tanda setuju dan taip nama. Kod pintu tersembunyi sehingga peraturan diterima dan ID disahkan.",
"A guest reports damage in the guest app": "Tetamu melaporkan kerosakan dalam aplikasi tetamu",
"Create a maintenance task with the photos and alert maintenance": "Cipta tugasan penyelenggaraan dengan foto dan maklumkan penyelenggaraan",
"Every damaged item needs a photo. The task is assigned to maintenance and linked to the booking for any deposit claim.": "Setiap barang rosak perlu ada foto. Tugasan diagih kepada penyelenggaraan dan dipautkan kepada tempahan untuk sebarang tuntutan deposit.",
"A guest checks out": "Tetamu daftar keluar",
"Create a turnover clean for the property's housekeeper": "Cipta pembersihan pusingan untuk pengemas hartanah",
"Due 15 minutes before the next check-in, or 3:00 PM if nobody arrives that day.": "Perlu siap 15 minit sebelum daftar masuk seterusnya, atau 3:00 petang jika tiada tetamu tiba hari itu.",
"A guest reports a problem in a message": "Tetamu melaporkan masalah dalam mesej",
"Create a maintenance task and alert the ops manager": "Cipta tugasan penyelenggaraan dan maklumkan pengurus operasi",
"Picks up words like AC, leak, broken, no water, no hot water, smell.": "Mengesan perkataan seperti AC, bocor, rosak, tiada air, tiada air panas, bau.",
"A review is 3 stars or lower": "Ulasan 3 bintang atau kurang",
"Alert the ops manager and draft a reply": "Maklumkan pengurus operasi dan draf balasan",
"The reply stays a draft until someone posts it from Reviews.": "Balasan kekal draf sehingga seseorang menyiarkannya dari Ulasan.",
