"Turn off the house rules check? Guests will see their door code without accepting the house rules.": "Matikan semakan peraturan rumah? Tetamu akan nampak kod pintu tanpa menerima peraturan rumah.",
"Turn off automatic invoices? New bookings will need an invoice sent by hand from Invoices & Receipts.": "Matikan invois automatik? Tempahan baharu perlu dihantar invois secara manual dari Invois & Resit.",
"Turn off automatic receipts? Guests will not get a receipt when they pay unless someone sends it.": "Matikan resit automatik? Tetamu tidak akan terima resit apabila membayar melainkan seseorang menghantarnya.",
"Turn off same-day alerts? Late bookings for today will not alert anyone or create an urgent clean.": "Matikan amaran hari yang sama? Tempahan lewat untuk hari ini tidak akan memaklumkan sesiapa atau mencipta pembersihan segera.",
