"yet, and messaging guests is not part of your access": "dan menghantar mesej kepada tetamu bukan sebahagian daripada akses anda",
"Conversation": "Perbualan",
"Choose a chat": "Pilih sembang",
"Pick a guest on the left to read and reply. Messages, photos, files and voice notes all live in one thread per stay.": "Pilih tetamu di sebelah kiri untuk baca dan balas. Mesej, foto, fail dan nota suara semuanya dalam satu bebenang setiap penginapan.",
"Guest chats show up here": "Sembang tetamu dipaparkan di sini",
"When a guest books or messages you, their chat opens here with the stay details next to it.": "Apabila tetamu menempah atau menghantar mesej, sembang mereka dibuka di sini bersama butiran penginapan.",
"Messages": "Mesej",
"Recording discarded because you opened another chat": "Rakaman dibuang kerana anda membuka sembang lain",
"Writing internal notes is not part of your access": "Menulis nota dalaman bukan sebahagian daripada akses anda",
"Sent to": "Dihantar kepada",
"Internal note added. The guest cannot see it.": "Nota dalaman ditambah. Tetamu tidak dapat melihatnya.",
"Only photos and videos can go to guests from Orbique. Send documents and voice notes as an internal note, or from WhatsApp on your phone.": "Hanya foto dan video boleh dihantar kepada tetamu dari Orbique. Hantar dokumen dan nota suara sebagai nota dalaman, atau dari WhatsApp di telefon anda.",
"The message was not sent. Please try again.": "Mesej tidak dihantar. Sila cuba lagi.",
